        QXhx14 orderShipment = QXhx14.xhx14;
        QXrd81 user = QXrd81.xrd81;


        BooleanBuilder whereBuilder = new BooleanBuilder();


        if (StringUtils.hasText(email)) {
            whereBuilder.and(user.email.eq(email));
